class Solution { public int[] platesBetweenCandles(String s,int[][] queries){int n=s.length();int[] prefix=new int[n+1],left=new int[n],right=new int[n];int candle=-1;for(int i=0;i<n;i++){prefix[i+1]=prefix[i]+(s.charAt(i)=='*'?1:0);if(s.charAt(i)=='|')candle=i;left[i]=candle;}candle=-1;for(int i=n-1;i>=0;i--){if(s.charAt(i)=='|')candle=i;right[i]=candle;}int[] answer=new int[queries.length];for(int i=0;i<queries.length;i++){int start=right[queries[i][0]],end=left[queries[i][1]];if(start>=0&&start<end)answer[i]=prefix[end]-prefix[start];}return answer;} }
